SELECT developer_snippet_id, member_id, snippet_title, snippet_description, snippet_language, snippet_code, CAST(tags_json AS CHAR) AS tags_json, favorite_yn, use_yn, deleted_at, created_at, updated_at FROM developer_snippets
ORDER BY snippet_title, developer_snippet_id DESC ORDER BY favorite_yn DESC, updated_at DESC, developer_snippet_id DESC ORDER BY updated_at DESC, developer_snippet_id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE developer_snippets SET use_yn = 'N', deleted_at = CURRENT_TIMESTAMP(6)
WHERE member_id = #{memberId} AND use_yn = 'Y' AND developer_snippet_id IN
#{snippetId}

UPDATE developer_snippets SET use_yn = 'Y', deleted_at = NULL
WHERE member_id = #{memberId} AND use_yn = 'N' AND developer_snippet_id IN
#{snippetId}
